378: function addTranslation(map, module, key, translation, conflicts) {
379:     const previous = map[module]?.[key];
380:     if (previous !== undefined && previous !== translation) {
381:         conflicts.add(`${module}::${key}`);
382:         return false;
383:     }
384:     (map[module] ??= {})[key] = translation;
385:     return true;
386: }
387: 
388: function sortMap(map) {
389:     const sorted = {};
390:     for (const module of Object.keys(map).sort()) {
391:         sorted[module] = {};
392:         for (const key of Object.keys(map[module]).sort()) sorted[module][key] = map[module][key];
393:     }
394:     return sorted;
395: }
