452:         if (conflicts.size)
453:             console.warn(`  conflicting translations: ${[...conflicts].slice(0, 5).join(', ')}${conflicts.size > 5 ? '…' : ''}`);
454:         if (placeholderMismatches.size)
455:             console.warn(`  placeholder mismatches: ${[...placeholderMismatches].slice(0, 5).join(', ')}${placeholderMismatches.size > 5 ? '…' : ''}`);
456:         const byModule = new Map();
457:         for (const miss of misses) byModule.set(miss.module, (byModule.get(miss.module) ?? 0) + 1);
458:         const top = [...byModule].sort((a, b) => b[1] - a[1]).slice(0, 5);
459:         if (top.length) console.log(`  top misses: ${top.map(([module, count]) => `${module} (${count})`).join(', ')}`);
460:         if (verbose) {
