const fs = require('fs');
const path = require('path');
const roots = ['calcpad-frontend/src', 'calcpad-web/src', 'vscode-calcpad/src'];
const files = [];
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const f = path.join(d, e.name);
    if (e.isDirectory()) walk(f);
    else if (/\.(ts|vue)$/.test(e.name)) files.push(f);
  }
}
for (const r of roots) if (fs.existsSync(r)) walk(r);
const rows = [];
for (const f of files) {
  const lines = fs.readFileSync(f, 'utf8').split('\n');
  lines.forEach((line, i) => {
    for (const m of line.matchAll(/\b(t|tt)\(\s*([^'"`\s][^,)]*)/g)) {
      rows.push({ file: f, line: i + 1, call: m[1], expr: m[2].trim(), text: line.trim() });
    }
  });
}
console.log('dynamic t/tt calls:', rows.length);
for (const r of rows) console.log(`${r.file}:${r.line} ${r.call}(${r.expr})  ${r.text.slice(0, 120)}`);
EOF

